-- 071a DRY RUN - GENERATED by worker/migrations/drafts/tools/build-071a.mjs. DO NOT EDIT BY HAND.
-- WHY ONE DO BLOCK: the Supabase SQL editor is NOT atomic across statements (lesson 056), but ONE DO block is
--   ONE statement: its final error undoes everything inside it. ASCII only.
-- WHAT: 071a's own block, statement for statement (every guard, the three rewrites and their proofs, the two
--   auditor rows), then a read of the result, ENDING WITH A DELIBERATE ERROR: NOTHING is kept.
-- WHEN: after 15:00, BEFORE 071a_invoice_from_registration.sql.
-- EXPECTED (the red ERROR is deliberate): a NOTICE "071a OK: ..." and then
--   ERROR: P0001: DRY RUN 071a finished - EVERYTHING UNDONE, nothing kept  ||  lots <md5> orders <md5> natl <md5> S-03 false B-15 <md5>
--   Anything else (an ERROR from one of 071a's guards): do NOT run 071a, copy the message to the coordinator.

DO $dry$
DECLARE
  res text;
BEGIN
  -- ===== 071a_invoice_from_registration.sql, verbatim =====
  DECLARE
    r record; g text; src text; acl_before text; k int; m text;
  trg_before int; trg_after int;
  want CONSTANT jsonb := '{"stock_guard_lots": ["46e61e5f4c1e74af19cba5ddaa9f2975", "231b539e429f5d404d0eaa46618d79c5"], "stock_guard_orders": ["20833484dffdf168b1e1de9fdc242027", "63aa751d93cc8b34afa5587912de7045"], "stock_guard_natl": ["26b4cc060ab15152a51693c9f0a67f81", "e941edbca9ff1bbeba0c89d49eb71cb3"]}';
BEGIN
  -- CREATE OR REPLACE FUNCTION waits for no table lock, but a stuck session could still hold the
  -- function: give up after 5 s instead of queueing - the whole block rolls back, run it again later.
  PERFORM set_config('lock_timeout', '5s', true);

  -- 0. GUARDS (read only): the base is what was measured 22/10/2026.
  IF to_regclass('monitoring.checks') IS NULL THEN
    RAISE EXCEPTION '071a: monitoring.checks does not exist (047 must run first)';
  END IF;
  FOREACH g IN ARRAY ARRAY['stock_guard_lots', 'stock_guard_orders', 'stock_guard_natl'] LOOP
    SELECT md5(p.prosrc) INTO m FROM pg_proc p WHERE p.oid = to_regprocedure('public.' || g || '()');
    IF m IS NOT DISTINCT FROM want->g->>1 THEN
      RAISE EXCEPTION '071a: % already holds the 071a text - run 071a_invoice_from_registration_verify.sql instead', g;
    END IF;
    IF m IS DISTINCT FROM want->g->>0 THEN
      RAISE EXCEPTION '071a: % is not the 057 text read 22/10 (md5 %) - stop, re-measure', g, m;
    END IF;
    IF EXISTS (SELECT 1 FROM pg_proc p WHERE p.oid = to_regprocedure('public.' || g || '()')
                AND (p.prosecdef OR p.proconfig IS DISTINCT FROM ARRAY['search_path=public'])) THEN
      RAISE EXCEPTION '071a: % is SECURITY DEFINER or has another search_path than 057 gave it - stop', g;
    END IF;
  END LOOP;
  IF (SELECT count(*) FROM pg_trigger WHERE NOT tgisinternal AND tgenabled = 'O' AND tgname = ANY (ARRAY['stock_guard_lots', 'stock_guard_orders', 'stock_guard_natl'])) <> 3 THEN
    RAISE EXCEPTION '071a: the three stock_guard triggers are not all enabled (S-02) - stop';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM monitoring.checks WHERE id = 'S-03' AND enabled AND md5(sql_text) = '0df9746599fb62724c719d2f467ff280') THEN
    RAISE EXCEPTION '071a: auditor S-03 is not the enabled check read 22/10 - stop, re-measure';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM monitoring.checks WHERE id = 'B-15' AND md5(sql_text) = '40d8808efe298f7321a8706dc726a784') THEN
    RAISE EXCEPTION '071a: auditor B-15 is not the text read 22/10 - stop, re-measure';
  END IF;
  SELECT count(*) INTO trg_before FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid JOIN pg_namespace ns ON ns.oid = c.relnamespace
   WHERE NOT t.tgisinternal AND t.tgenabled <> 'D' AND ns.nspname = 'public';
  IF NOT EXISTS (SELECT 1 FROM monitoring.checks WHERE id = 'B-54' AND red_value = trg_before AND baseline IS NULL) THEN
    RAISE EXCEPTION '071a: B-54 red_value is not the live trigger count % - a migration changed triggers without bumping it, re-measure', trg_before;
  END IF;

  -- 1. The three guards, each from its LIVE text with the substitutions of
  --    worker/migrations/drafts/tools/build-071a.mjs (old text as base64: it holds Greek).
  FOREACH g IN ARRAY ARRAY['stock_guard_lots', 'stock_guard_orders', 'stock_guard_natl'] LOOP
    SELECT p.prosrc, p.proacl::text INTO src, acl_before FROM pg_proc p WHERE p.oid = ('public.' || g || '()')::regprocedure;
    FOR r IN
      SELECT s.seq, convert_from(decode(s.old_b64, 'base64'), 'UTF8') AS old_t, s.new_t
        FROM (VALUES
      ('stock_guard_lots', 1, 'ICAgIHZfaW52b2ljZWQgYm9vbGVhbjsK', ''),
      ('stock_guard_lots', 2, '', '    -- 071a (owner 21/10/2026): the source''s invoice no longer judges anything here: an invoiced
    -- lot is marked, closed, reopened and unmarked like any other.

'),
      ('stock_guard_lots', 3, 'ICAgICAgaWYgdl9pbnZvaWNlZCB0aGVuCiAgICAgICAgcGVyZm9ybSBzdG9ja19yYWlzZSgnbG90X2ludm9pY2VkJywgJ86XIM+AzrHPgc+Ezq/OtM6xIM+EzrnOvM6/zrvOv86zzq7OuM63zrrOtSDigJQgzrTOtc69IM66zrHPhM6xz4HOs861zq/PhM6xzrknKTsKICAgICAgZW5kIGlmOwo=', ''),
      ('stock_guard_lots', 4, 'aXMgZGlzdGluY3QgZnJvbSBvbGQud2FyZWhvdXNlX2NoYXJnZSBhbmQgdl9pbnZvaWNlZCB0aGVu', 'is distinct from old.warehouse_charge and <source invoiced> then'),
      ('stock_guard_lots', 5, '', '        if public.order_pallets(o) <= 0 then'),
      ('stock_guard_lots', 6, 'ICAgICAgICBpZiBjb2FsZXNjZShuLmludm9pY2VkLCBmYWxzZSkgdGhlbgogICAgICAgICAgcGVyZm9ybSBzdG9ja19yYWlzZSgnbG90X2ludm9pY2VkJywgJ86kzrnOvM6/zrvOv86zzrfOvM6tzr3OtyDPgM6xz4HOsc6zzrPOtc67zq/OsSDOtM61zr0gzrPOr869zrXPhM6xzrkgz4DOsc+Bz4TOr860zrEnKTsKICAgICAgICBlbmQgaWY7Cg==', ''),
      ('stock_guard_lots', 7, 'ICAgICAgaWYgdl9pbnZvaWNlZCB0aGVuCiAgICAgICAgcGVyZm9ybSBzdG9ja19yYWlzZSgncmVvcGVuX2ludm9pY2VkJywgJ86kzrnOvM6/zrvOv86zzrfOvM6tzr3OtyDPgM6xz4HPhM6vzrTOsSDOtM61zr0gzr7Osc69zrHOvc6/zq/Os861zrknKTsKICAgICAgZW5kIGlmOwo=', ''),
      ('stock_guard_lots', 8, 'ICAgICAgaWYgdl9pbnZvaWNlZCB0aGVuCiAgICAgICAgcGVyZm9ybSBzdG9ja19yYWlzZSgnbG90X2ludm9pY2VkJywgJ86XIM+AzrHPgc+Ezq/OtM6xIM+EzrnOvM6/zrvOv86zzq7OuM63zrrOtSDigJQgzrTOtc69IM6xzrvOu86szrbOtc65Jyk7CiAgICAgIGVuZCBpZjsK', ''),
      ('stock_guard_orders', 1, 'ICAgIHZfZG9uZSAgICBiaWdpbnQ7Cg==', ''),
      ('stock_guard_orders', 2, '', '        -- Locked like a draw (D-22). 071a (owner 21/10/2026): the lot''s invoice no longer refuses a delete.
        perform 1 from public.stock_lots s where s.id = new.stock_lot_id for no key update;
'),
      ('stock_guard_orders', 3, 'c2VsZWN0IHYuY2xpZW50X2lkLCB2LndhcmVob3VzZV9sb2NhdGlvbl9pZCwgdi5vcHNfc3RhdHVzLCB2Lmludm9pY2VkLCB2LmNsb3NlZF9hdCwgdi5zdG9ja19wYWxsZXRzLCB2LmludGFrZV9zdGF0dXM=', 'select v.client_id, v.warehouse_location_id, v.ops_status, v.closed_at, v.stock_pallets, v.intake_status'),
      ('stock_guard_orders', 4, 'ICAgICAgICBpZiBzdC5pbnZvaWNlZCB0aGVuCiAgICAgICAgICBwZXJmb3JtIHN0b2NrX3JhaXNlKCdsb3RfaW52b2ljZWQnLCAnzpcgz4DOsc+Bz4TOr860zrEgz4TOuc68zr/Ou86/zrPOrs64zrfOus61IOKAlCDOsc69zrHOr8+BzrXPg861IM+Az4HPjs+EzrEgz4TOvyDPhM65zrzOv867z4zOs865zr8nKTsKICAgICAgICBlbmQgaWY7Cg==', '        -- 071a (owner 21/10/2026): an invoiced lot still gives pieces (invoiced from registration).
'),
      ('stock_guard_orders', 5, '', '      -- 071a (owner 21/10/2026): the lot''s invoice no longer freezes a piece''s status (the round-1
      -- freeze assumed the invoice came last; it now comes first). A piece LEAVING Delivered still takes
      -- the lot lock, FOR NO KEY UPDATE like every draw (D-22): the close reads "all delivered".
      if tg_op = ''UPDATE'' and not v_revived and new.status is distinct from old.status
         and old.status = ''Delivered'' then
        perform 1 from public.stock_lots s where s.id = new.stock_lot_id for no key update;
      end if;
'),
      ('stock_guard_orders', 6, 'ICAgICAgc2VsZWN0IGNvdW50KCopLCBjb3VudCgqKSBmaWx0ZXIgKHdoZXJlIHAuZGVsaXZlcmVkKSwgY29hbGVzY2Uoc3VtKHAucGFsbGV0cyksIDApCiAgICAgICAgaW50byB2X3BpZWNlcywgdl9kb25lLCB2X2RyYXduCg==', '      select count(*), coalesce(sum(p.pallets), 0)
        into v_pieces, v_drawn
'),
      ('stock_guard_orders', 7, '', '        -- 071a (owner 21/10/2026): the intake''s status follows the warehouse after the invoice too.
'),
      ('stock_guard_orders', 8, 'Q2xlYXJpbmcKICAgICAgICAtLSDCq0ludm9pY2VkwrsgaW4gdGhlIHNhbWUgc2F2ZSBwYXNzZXMsIGxpa2UgdGhlIHN0YXR1cyBmcmVlemUgYWJvdmUu', 'Clearing
        -- the invoice in the same save passes. 071a keeps THIS rule: the invoice states the price.'),
      ('stock_guard_orders', 9, '', '      -- 071a (owner 21/10/2026): a lot is invoiced like any order, from its registration. The
      -- old "one invoice only when everything arrived" refusal (invoice_incomplete) is gone.
'),
      ('stock_guard_natl', 1, 'ICAgIHZfZG9uZSAgICBiaWdpbnQ7Cg==', ''),
      ('stock_guard_natl', 2, '', '        perform 1 from public.stock_lots s where s.id = new.stock_lot_id for no key update;
        -- 071a (owner 21/10/2026): the lot''s invoice no longer refuses a delete.
        if old.status = ''In Transit'''),
      ('stock_guard_natl', 3, 'c2VsZWN0IHYuY2xpZW50X2lkLCB2LndhcmVob3VzZV9sb2NhdGlvbl9pZCwgdi5vcHNfc3RhdHVzLCB2Lmludm9pY2VkLCB2LmNsb3NlZF9hdCwgdi5zdG9ja19wYWxsZXRzLCB2LmludGFrZV9zdGF0dXM=', 'select v.client_id, v.warehouse_location_id, v.ops_status, v.closed_at, v.stock_pallets, v.intake_status'),
      ('stock_guard_natl', 4, 'ICAgICAgICBpZiBzdC5pbnZvaWNlZCB0aGVuCiAgICAgICAgICBwZXJmb3JtIHN0b2NrX3JhaXNlKCdsb3RfaW52b2ljZWQnLCAnzpcgz4DOsc+Bz4TOr860zrEgz4TOuc68zr/Ou86/zrPOrs64zrfOus61IOKAlCDOsc69zrHOr8+BzrXPg861IM+Az4HPjs+EzrEgz4TOvyDPhM65zrzOv867z4zOs865zr8nKTsKICAgICAgICBlbmQgaWY7Cg==', '        -- 071a (owner 21/10/2026): an invoiced lot still gives pieces (invoiced from registration).
'),
      ('stock_guard_natl', 5, '', '      -- 071a (owner 21/10/2026): the lot''s invoice no longer freezes a piece''s status or date
      -- (see stock_guard_orders). A piece LEAVING delivered still takes the lot lock (D-22).
      if tg_op = ''UPDATE'' and not v_revived
         and (new.status is distinct from old.status
              or public.stock_natl_delivered(new.status, new.delivery_datetime)
                 is distinct from public.stock_natl_delivered(old.status, old.delivery_datetime))
         and public.stock_natl_delivered(old.status, old.delivery_datetime) then
        perform 1 from public.stock_lots s where s.id = new.stock_lot_id for no key update;
      end if;
'),
      ('stock_guard_natl', 6, 'ICAgICAgc2VsZWN0IGNvdW50KCopLCBjb3VudCgqKSBmaWx0ZXIgKHdoZXJlIHAuZGVsaXZlcmVkKSwgY29hbGVzY2Uoc3VtKHAucGFsbGV0cyksIDApCiAgICAgICAgaW50byB2X3BpZWNlcywgdl9kb25lLCB2X2RyYXduCg==', '      select count(*), coalesce(sum(p.pallets), 0)
        into v_pieces, v_drawn
'),
      ('stock_guard_natl', 7, '', '        -- 071a (owner 21/10/2026): the intake''s status follows the warehouse after the invoice too.
'),
      ('stock_guard_natl', 8, '', '      -- 071a (owner 21/10/2026): a lot is invoiced like any order, from its registration
      -- (invoice_incomplete is gone, see stock_guard_orders).
')
        ) AS s(fname, seq, old_b64, new_t)
       WHERE s.fname = g ORDER BY s.seq
    LOOP
      k := (length(src) - length(replace(src, r.old_t, ''))) / length(r.old_t);
      IF k <> 1 THEN
        RAISE EXCEPTION '071a: % substitution % found % times (expected exactly 1) - stop', g, r.seq, k;
      END IF;
      src := replace(src, r.old_t, r.new_t);
    END LOOP;
    IF md5(src) <> want->g->>1 THEN
      RAISE EXCEPTION '071a: the generated % is not the text built and tested (md5 %) - stop', g, md5(src);
    END IF;
    -- CREATE OR REPLACE keeps the oid, the owner, the grants and the trigger that calls it.
    EXECUTE format('CREATE OR REPLACE FUNCTION public.%I() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS %L', g, src);
    IF (SELECT md5(p.prosrc) FROM pg_proc p WHERE p.oid = ('public.' || g || '()')::regprocedure) <> want->g->>1
       OR (SELECT p.proacl::text FROM pg_proc p WHERE p.oid = ('public.' || g || '()')::regprocedure) IS DISTINCT FROM acl_before THEN
      RAISE EXCEPTION '071a proof: % does not hold the generated text, or its grants changed', g;
    END IF;
  END LOOP;

  -- 2. AUDITOR (text = tms-auditor/checks/S-03.sql and B-15.sql, the files the 047b seed is built from).
  --    S-03 "invoiced lot not complete" was the P1 alarm of the old one-invoice rule: from today it is a
  --    normal state, an hourly false P1 would teach everyone to ignore the true ones. Disabled, never
  --    deleted: a disabled check is reported as a GAP with its reason.
  UPDATE monitoring.checks
     SET enabled = false, disabled_reason = convert_from(decode('', 'base64'), 'UTF8')
   WHERE id = 'S-03' AND enabled AND md5(sql_text) = '0df9746599fb62724c719d2f467ff280';
  GET DIAGNOSTICS k = ROW_COUNT;
  IF k <> 1 THEN RAISE EXCEPTION '071a: S-03 not disabled (% rows)', k; END IF;
  --    B-15 (queue, P3): a lot counts from its own delivery like every order - the same rule as the
  --    screen's OrdersData.ageOf (one rule, principle 3). Before: from the day the lot became complete.
  UPDATE monitoring.checks SET sql_text = 'SELECT count(*) FROM orders o WHERE o.deleted_at IS NULL AND o.status=''Delivered'' AND o.invoiced IS NOT TRUE AND o.parent_order_id IS NULL AND o.stock_lot_id IS NULL AND coalesce(o.actual_delivery_date,o.delivery_datetime) < current_date-30'
   WHERE id = 'B-15' AND md5(sql_text) = '40d8808efe298f7321a8706dc726a784';
  GET DIAGNOSTICS k = ROW_COUNT;
  IF k <> 1 THEN RAISE EXCEPTION '071a: B-15 not updated (% rows)', k; END IF;

  -- 3. B-54: no trigger is added or dropped.
  SELECT count(*) INTO trg_after FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid JOIN pg_namespace ns ON ns.oid = c.relnamespace
   WHERE NOT t.tgisinternal AND t.tgenabled <> 'D' AND ns.nspname = 'public';
  IF trg_after <> trg_before THEN
    RAISE EXCEPTION '071a proof: trigger count % -> % (expected unchanged)', trg_before, trg_after;
  END IF;

  RAISE NOTICE '071a OK: stock_guard_lots/_orders/_natl rewritten (only the lot price still freezes with the invoice), S-03 disabled, B-15 counts lots from their delivery, triggers % unchanged', trg_after;
  END;
  -- ===== what it did =====
  res := format('lots %s orders %s natl %s S-03 %s B-15 %s',
    (SELECT md5(prosrc) FROM pg_proc WHERE oid = 'public.stock_guard_lots()'::regprocedure),
    (SELECT md5(prosrc) FROM pg_proc WHERE oid = 'public.stock_guard_orders()'::regprocedure),
    (SELECT md5(prosrc) FROM pg_proc WHERE oid = 'public.stock_guard_natl()'::regprocedure),
    (SELECT enabled FROM monitoring.checks WHERE id = 'S-03'),
    (SELECT md5(sql_text) FROM monitoring.checks WHERE id = 'B-15'));
  RAISE EXCEPTION 'DRY RUN 071a finished - EVERYTHING UNDONE, nothing kept  ||  %', res;
END
$dry$;
